from calculator_class import Calculatorcalculator = Calculator()class CalculatorApp:    def __init__(self):        self.calculator = calculator        self.calculator_menu = {            "1":("ADDITION",self.calculator.Addition),            "2":("SUBTRACTION",self.calculator.Subtraction),            "3":("MULTIPLICATION",self.calculator.Multiplication),            "4":("DIVISION",self.calculator.Division)}    def main(self):        while True:            for key, value in self.calculator_menu.items():                print(f"{key}:{value[0]}")            choice = input("Enter your choice 1 TO 4: ")            if choice not in self.calculator_menu.keys():                    print("\033[31mInvalid choice, plese try again\033[0m")                    continue            number_1 = float(input("Enter first number: "))            number_2 = float(input("Enter second number: "))            operation_name = self.calculator_menu[choice][0]            operation_function = self.calculator_menu[choice][1]            result = operation_function(number_1, number_2)            print(f"{operation_name}: Answer is = {result}")if __name__ == "__main__":    app = CalculatorApp()    app.main()